"""C code, manifest and simulation setup of a generated application
(model of rttools.ucxgen.model)."""
from __future__ import annotations

import json

HEADER = """\
/*
 * {name}.c: UCX-OS application generated by rttools.ucxgen (orca-rt-tools).
 * Do not edit: change the inputs and run the generator again.
 *
 *   python -m rttools.ucxgen generate {csv} {map} --name {name} \\
 *     --mesh {mesh} --cycles-per-count {cpc} --reserve {reserve} \\
 *     --payload-divisor {div} --tag-mod {tag_mod} --delay-ns {delay}
 *
 * Inputs: {csv} (sha256 {csv_sha})
 *         {map} (sha256 {map_sha})
 * {n_tasks} tasks, {n_flows} flows ({n_remote} between PEs), mesh {mesh}; release every
 * {period} ns after {delay} ns on the PEs of the source tasks ({release_pes}).
 *
 * Pattern of weird_a.c (application E). A source task blocks until the
 * release interrupt (irq4_handler of this file; the kernel is built
 * without its own handler, -DUCX_APP_IRQ4). Every other task runs
 * iteration k after it has received the k-th packet of each input edge
 * (source port of the packet; FIFO queues). Then the task waits
 * ucx_sleep(workload) cycles, workload = (c(v) - {reserve}) / {cpc}
 * ({cpc} cycles per count of ucx_sleep, kernel/ucx.c), and sends one
 * packet per output edge with tag = flow * TAG_MOD + (k mod TAG_MOD)
 * (flow = index of the edge in the CSV, from 1). A packet to a task of the
 * same PE goes to the local queue of the target task (lib/noc.c). On each
 * PE, app_main creates the tasks in the creation order of the model; the
 * kernel dispatches them in the order of the model (dispatch_order).
 *
 * Iteration markers (include/device/cacc.h, as weird_a.c): each task
 * writes ITER_BEGIN(letter, k) when it has the input of iteration k (a
 * source task after the release) and ITER_END(letter, k) after its last
 * send of iteration k (after the work, for a task without output edge);
 * the PE prints `<t> <x-y> ITER begin|end <letter> <k>` (manycore_pe.sv).
 * The letter of each task is in the manifest (iter_letter); a run that
 * serves iterations k and k + 1 writes the markers of both.
 */
"""

BODY = """\
#include <ucx.h>

#define N_TASKS     {n_tasks}
#define MAX_IN      {max_in}
#define MAX_OUT     {max_out}
#define MAX_RELEASE {max_release}
#define TAG_MOD     {tag_mod}
#define TAG(flow, k) ((uint16_t)((flow) * TAG_MOD + ((k) % TAG_MOD)))
#define ITERATIONS  99999

struct out_s {{
  uint16_t cpu;    /* PE of the target task (node index) */
  uint16_t port;   /* port of the target task */
  uint16_t bytes;  /* payload */
  uint16_t flow;   /* index of the edge (tag) */
}};

struct task_s {{
  char name[5];
  char letter;                    /* letter of the iteration markers */
  uint16_t port;
  int32_t workload;               /* counts of ucx_sleep */
  uint8_t n_in, n_out;
  uint16_t in_port[MAX_IN];       /* port of the source task of each input edge */
  struct out_s out[MAX_OUT];
}};

static const struct task_s TASKS[N_TASKS] = {{
{tasks}
}};

/* ------------------------------ release */
static struct tcb_s *release_tcb[MAX_RELEASE];
static int n_release = 0;

/* release of the source tasks of this PE (manycore_pe.sv, wake-up
 * generator; the kernel handler of application E marks task A of PE 0) */
void irq4_handler(void)
{{
  _di();
  for (int i = 0; i < n_release; i++)
    release_tcb[i]->state = TASK_READY;

  /* flag interruption down */
  volatile int *irq_flag_down = (volatile int *)(0x2000004C);
  *irq_flag_down = !(*irq_flag_down);
  _ei();
}}

/* ------------------------------ tasks */
static noc_packet_t *create_pkt(uint32_t bytes)
{{
  noc_packet_t *pkt = ucx_noc_create_packet(bytes);

  for (uint32_t i = 0; i < bytes; i++)
    pkt->data[i] = i;

  return pkt;
}}

static void sleep_forever(void)
{{
  kcb_p->tcb_p->state = TASK_STOPPED;
  ucx_task_yield();
}}

/* blocking receive (recv_source_port of weird_a.c); counts the packet on
 * its input edge and checks the iteration of the tag of a packet from
 * another PE (a local packet is the buffer of the sender) */
static void receive_one(const struct task_s *t, uint32_t *received)
{{
  while (ucx_noc_probe() <= 0) {{
    kcb_p->tcb_p->state = TASK_BLOCKED;
    ucx_task_yield();
  }}

  noc_packet_t *pkt = ucx_noc_receive();
  uint16_t port = pkt->source_port;
  uint16_t tag = pkt->tag;
  int remote = pkt->source_node != ucx_noc_cpu_id();

  if (remote)
    ucx_free(pkt);

  for (int i = 0; i < t->n_in; i++) {{
    if (t->in_port[i] == port) {{
      received[i]++;
      if (remote && tag % TAG_MOD != received[i] % TAG_MOD)
        printf("%s: tag %d on input %d, expected iteration %d\\n", t->name, tag, i, received[i]);
      return;
    }}
  }}
  printf("%s: packet from unknown port %d\\n", t->name, port);
}}

static void run_task(const struct task_s *t)
{{
  noc_packet_t *pkt[MAX_OUT];
  uint32_t received[MAX_IN];
  uint32_t done = 0;
  int it = ITERATIONS;

  ucx_noc_comm_create(t->port);
  for (int o = 0; o < t->n_out; o++)
    pkt[o] = create_pkt(t->out[o].bytes);
  for (int i = 0; i < MAX_IN; i++)
    received[i] = 0;

  do {{
    if (t->n_in == 0) {{
      /* voluntary sleep until the release */
      kcb_p->tcb_p->state = TASK_BLOCKED;
      ucx_task_yield();
    }} else {{
      /* wait for the packet of iteration done + 1 of each input edge */
      for (int i = 0; i < t->n_in; i++)
        while (received[i] <= done)
          receive_one(t, received);
    }}
    ITER_BEGIN(t->letter, done + 1);

    /* simulate processing */
    ucx_sleep(t->workload);
    done++;

    for (int o = 0; o < t->n_out; o++)
      ucx_noc_send(t->out[o].cpu, t->out[o].port, pkt[o], TAG(t->out[o].flow, done));
    ITER_END(t->letter, done);
  }} while (--it);

  for (int o = 0; o < t->n_out; o++)
    ucx_free(pkt[o]);
  sleep_forever();
}}

{task_functions}

void idle_task_p(void)
{{
  for (;;)
    ;
}}

static void add_task(void (*fn)(void), const struct task_s *t)
{{
  ucx_task_add(fn, (char *)t->name, DEFAULT_STACK_SIZE, 0, 0, 0);
  if (t->n_in == 0 && n_release < MAX_RELEASE)
    release_tcb[n_release++] = kcb_p->tcb_p;   /* tcb of the task just added */
}}

int32_t app_main(void)
{{
  /* idle must be ID = 0 */
  ucx_task_add(idle_task_p, "IDLE", DEFAULT_STACK_SIZE, 0, 0, 0);

  switch (ucx_noc_cpu_id()) {{
{cases}
  default:
    break;
  }}

  return 1;
}}
"""


WORK_HEADER = """\
 *
 * Bodies ({bodies}, rttools.ucxgen --bodies): instead of ucx_sleep, the
 * work of an iteration runs on an array of WORK_N = {work_n} words. A
 * source task fills it from the iteration number (xorshift32); every other
 * task XORs the payload words of each received packet into it (the count
 * comes from the payload size of the packet). Then `repeat` passes of the
 * body: sort (insertion sort, the shifts depend on the order of the
 * words), search (linear search of a key taken from the data, stops at the
 * first match) or count (a loop of (w[0] mod COUNT_MAX) + 1 passes,
 * COUNT_MAX = {count_max}). The first words of the array go into the
 * payload of every output packet. WCET_LOOP_BOUND and WCET_LOOP_TOTAL
 * (include/lib/wcet.h) give the loop bounds to rttools.wcet.
 */
"""

WORK_BODY = """\
#include <ucx.h>
#include <lib/wcet.h>

#define N_TASKS     {n_tasks}
#define MAX_IN      {max_in}
#define MAX_OUT     {max_out}
#define MAX_RELEASE {max_release}
#define TAG_MOD     {tag_mod}
#define TAG(flow, k) ((uint16_t)((flow) * TAG_MOD + ((k) % TAG_MOD)))
#define ITERATIONS  99999
#define WORK_N      {work_n}
#define COUNT_MAX   {count_max}
#define MAX_REPEAT  {max_repeat}

#define BODY_SLEEP  0
#define BODY_SORT   1
#define BODY_SEARCH 2
#define BODY_COUNT  3

struct out_s {{
  uint16_t cpu;    /* PE of the target task (node index) */
  uint16_t port;   /* port of the target task */
  uint16_t bytes;  /* payload */
  uint16_t flow;   /* index of the edge (tag) */
}};

struct task_s {{
  char name[5];
  char letter;                    /* letter of the iteration markers */
  uint16_t port;
  int32_t workload;               /* counts of ucx_sleep (body sleep) */
  uint8_t n_in, n_out;
  uint8_t body;                   /* BODY_* */
  uint8_t repeat;                 /* passes of the body per iteration */
  uint16_t in_port[MAX_IN];       /* port of the source task of each input edge */
  struct out_s out[MAX_OUT];
}};

static const struct task_s TASKS[N_TASKS] = {{
{tasks}
}};

/* ------------------------------ release */
static struct tcb_s *release_tcb[MAX_RELEASE];
static int n_release = 0;

/* release of the source tasks of this PE (manycore_pe.sv, wake-up
 * generator; the kernel handler of application E marks task A of PE 0) */
void irq4_handler(void)
{{
  _di();
  for (int i = 0; i < n_release; i++)
    release_tcb[i]->state = TASK_READY;

  /* flag interruption down */
  volatile int *irq_flag_down = (volatile int *)(0x2000004C);
  *irq_flag_down = !(*irq_flag_down);
  _ei();
}}

/* ------------------------------ work */
/* input of a source task: xorshift32 from the iteration and the port */
static void fill(uint32_t *w, uint32_t k, uint32_t port)
{{
  uint32_t x = (k << 8) ^ port ^ 0x9E3779B9u;

  for (int i = 0; i < WORK_N; i++) {{
    WCET_LOOP_BOUND(WORK_N);
    x ^= x << 13;
    x ^= x >> 17;
    x ^= x << 5;
    w[i] = x;
  }}
}}

/* XOR of the payload words of a packet into the work array; the count
 * comes from the payload size of the packet */
static void absorb(uint32_t *w, const noc_packet_t *pkt)
{{
  uint32_t n = pkt->payload_size / 4;
  const uint32_t *d = (const uint32_t *)pkt->data;

  if (n > WORK_N)
    n = WORK_N;
  for (uint32_t i = 0; i < n; i++) {{
    WCET_LOOP_BOUND(WORK_N);
    w[i] ^= d[i];
  }}
}}

/* first words of the work array into the payload of a packet */
static void emit(noc_packet_t *pkt, const uint32_t *w, uint32_t bytes)
{{
  uint32_t n = bytes / 4;
  uint32_t *d = (uint32_t *)pkt->data;

  if (n > WORK_N)
    n = WORK_N;
  for (uint32_t i = 0; i < n; i++) {{
    WCET_LOOP_BOUND(WORK_N);
    d[i] = w[i];
  }}
}}

/* insertion sort: the shifts depend on the order of the words; the inner
 * loop tests its condition at most i + 1 times for word i */
static __attribute__((noinline)) void body_sort(uint32_t *w)
{{
  for (int i = 1; i < WORK_N; i++) {{
    WCET_LOOP_BOUND(WORK_N);
    uint32_t x = w[i];
    int j = i;

    while (j > 0 && w[j - 1] > x) {{
      WCET_LOOP_TOTAL(WORK_N * (WORK_N - 1) / 2 + WORK_N - 1);
      w[j] = w[j - 1];
      j--;
    }}
    w[j] = x;
  }}
}}

/* linear search of the low byte `key`; stops at the first match */
static __attribute__((noinline)) int body_search(const uint32_t *w, uint32_t key)
{{
  for (int i = 0; i < WORK_N; i++) {{
    WCET_LOOP_BOUND(WORK_N);
    if ((w[i] & 0xFF) == key)
      return i;
  }}
  return -1;
}}

/* loop with a count from the data: (w[0] mod COUNT_MAX) + 1 passes */
static __attribute__((noinline)) void body_count(uint32_t *w)
{{
  uint32_t c = (w[0] & (COUNT_MAX - 1)) + 1;
  uint32_t acc = w[1];

  for (uint32_t i = 0; i < c; i++) {{
    WCET_LOOP_BOUND(COUNT_MAX);
    acc = (acc << 3) ^ (acc >> 5) ^ w[i & (WORK_N - 1)];
  }}
  w[1] = acc;
}}

static void run_body(const struct task_s *t, uint32_t *w, uint32_t k)
{{
  for (int r = 0; r < t->repeat; r++) {{
    WCET_LOOP_BOUND(MAX_REPEAT);
    if (t->body == BODY_SORT) {{
      body_sort(w);
      w[0] ^= k + r;
    }} else if (t->body == BODY_SEARCH) {{
      w[2] ^= (uint32_t)body_search(w, (w[0] >> 24) ^ r);
    }} else if (t->body == BODY_COUNT) {{
      body_count(w);
    }} else {{
      ucx_sleep(t->workload);
    }}
  }}
}}

/* ------------------------------ tasks */
static noc_packet_t *create_pkt(uint32_t bytes)
{{
  noc_packet_t *pkt = ucx_noc_create_packet(bytes);

  for (uint32_t i = 0; i < bytes; i++)
    pkt->data[i] = i;

  return pkt;
}}

static void sleep_forever(void)
{{
  kcb_p->tcb_p->state = TASK_STOPPED;
  ucx_task_yield();
}}

/* blocking receive (recv_source_port of weird_a.c); counts the packet on
 * its input edge, XORs its payload into the work array and checks the
 * iteration of the tag of a packet from another PE (a local packet is the
 * buffer of the sender) */
static void receive_one(const struct task_s *t, uint32_t *received, uint32_t *w)
{{
  while (ucx_noc_probe() <= 0) {{
    kcb_p->tcb_p->state = TASK_BLOCKED;
    ucx_task_yield();
  }}

  noc_packet_t *pkt = ucx_noc_receive();
  uint16_t port = pkt->source_port;
  uint16_t tag = pkt->tag;
  int remote = pkt->source_node != ucx_noc_cpu_id();

  absorb(w, pkt);
  if (remote)
    ucx_free(pkt);

  for (int i = 0; i < t->n_in; i++) {{
    if (t->in_port[i] == port) {{
      received[i]++;
      if (remote && tag % TAG_MOD != received[i] % TAG_MOD)
        printf("%s: tag %d on input %d, expected iteration %d\\n", t->name, tag, i, received[i]);
      return;
    }}
  }}
  printf("%s: packet from unknown port %d\\n", t->name, port);
}}

static void run_task(const struct task_s *t)
{{
  noc_packet_t *pkt[MAX_OUT];
  uint32_t received[MAX_IN];
  uint32_t work[WORK_N];
  uint32_t done = 0;
  int it = ITERATIONS;

  ucx_noc_comm_create(t->port);
  for (int o = 0; o < t->n_out; o++)
    pkt[o] = create_pkt(t->out[o].bytes);
  for (int i = 0; i < MAX_IN; i++)
    received[i] = 0;
  for (int i = 0; i < WORK_N; i++)
    work[i] = 0;

  do {{
    if (t->n_in == 0) {{
      /* voluntary sleep until the release */
      kcb_p->tcb_p->state = TASK_BLOCKED;
      ucx_task_yield();
      fill(work, done + 1, t->port);
    }} else {{
      /* wait for the packet of iteration done + 1 of each input edge */
      for (int i = 0; i < t->n_in; i++)
        while (received[i] <= done)
          receive_one(t, received, work);
    }}
    ITER_BEGIN(t->letter, done + 1);

    run_body(t, work, done + 1);
    done++;

    for (int o = 0; o < t->n_out; o++) {{
      emit(pkt[o], work, t->out[o].bytes);
      ucx_noc_send(t->out[o].cpu, t->out[o].port, pkt[o], TAG(t->out[o].flow, done));
    }}
    ITER_END(t->letter, done);
  }} while (--it);

  for (int o = 0; o < t->n_out; o++)
    ucx_free(pkt[o]);
  sleep_forever();
}}

{task_functions}

void idle_task_p(void)
{{
  for (;;)
    ;
}}

static void add_task(void (*fn)(void), const struct task_s *t)
{{
  ucx_task_add(fn, (char *)t->name, DEFAULT_STACK_SIZE, 0, 0, 0);
  if (t->n_in == 0 && n_release < MAX_RELEASE)
    release_tcb[n_release++] = kcb_p->tcb_p;   /* tcb of the task just added */
}}

int32_t app_main(void)
{{
  /* idle must be ID = 0 */
  ucx_task_add(idle_task_p, "IDLE", DEFAULT_STACK_SIZE, 0, 0, 0);

  switch (ucx_noc_cpu_id()) {{
{cases}
  default:
    break;
  }}

  return 1;
}}
"""

BODY_CODES = {"sleep": "BODY_SLEEP", "sort": "BODY_SORT", "search": "BODY_SEARCH", "count": "BODY_COUNT"}


def c_string(s):
    return '"' + s.replace("\\", "\\\\").replace('"', '\\"') + '"'


def task_row(t, flows, tasks_by_name, max_in, max_out):
    ins = [tasks_by_name[flows[i - 1]["source"]]["port"] for i in t["inputs"]]
    outs = []
    for i in t["outputs"]:
        f = flows[i - 1]
        outs.append(f"{{{f['dst_pe']}, {tasks_by_name[f['target']]['port']}, {f['bytes']}, {f['id']}}}")
    in_txt = "{" + ", ".join(str(p) for p in ins or [0]) + "}"
    out_txt = "{" + ", ".join(outs or ["{0, 0, 0, 0}"]) + "}"
    kname = t["name"][:4]
    if "body" in t:
        return (f"  /* {t['name']}: PE {t['pe']} ({t['pe_label']}), position {t['order']}, body {t['body']} "
                f"x {t['repeat']}, marker {t['iter_letter']} */\n"
                f"  {{{c_string(kname)}, '{t['iter_letter']}', {t['port']}, {t['workload']}, {len(ins)}, "
                f"{len(t['outputs'])}, {BODY_CODES[t['body']]}, {t['repeat']}, "
                f"{in_txt}, {out_txt}}},")
    return (f"  /* {t['name']}: PE {t['pe']} ({t['pe_label']}), position {t['order']}, c(v) = {t['wcet']}, "
            f"marker {t['iter_letter']} */\n"
            f"  {{{c_string(kname)}, '{t['iter_letter']}', {t['port']}, {t['workload']}, {len(ins)}, "
            f"{len(t['outputs'])}, "
            f"{in_txt}, {out_txt}}},")


def c_source(m):
    if m.get("model") == "time_triggered":
        return tt_source(m)
    flows = m["flows"]
    tasks = m["tasks"]
    by_name = {t["name"]: t for t in tasks}
    index = {t["name"]: i for i, t in enumerate(tasks)}
    max_in = max(1, max(len(t["inputs"]) for t in tasks))
    max_out = max(1, max(len(t["outputs"]) for t in tasks))
    per_pe = {}
    for t in tasks:
        per_pe.setdefault(t["pe"], []).append(t)
    max_release = max(1, max(sum(t["source"] for t in ts) for ts in per_pe.values()))
    rows = "\n".join(task_row(t, flows, by_name, max_in, max_out) for t in tasks)
    funcs = "\n".join(f"static void task_{t['ident']}(void) {{ run_task(&TASKS[{index[t['name']]}]); }}"
                      for t in tasks)
    cases = []
    for node in sorted(per_pe):
        ts = sorted(per_pe[node], key=lambda t: t["order"])
        cases.append(f"  case {node}: /* ({ts[0]['pe_label']}): {', '.join(t['name'] for t in ts)} */")
        for t in ts:
            cases.append(f"    add_task(task_{t['ident']}, &TASKS[{index[t['name']]}]);")
        cases.append("    break;")
    w, h = m["mesh"]
    if m.get("apps"):
        head = composition_header(m)
        return head + BODY.format(n_tasks=len(tasks), max_in=max_in, max_out=max_out,
                                  max_release=max_release, tag_mod=m["tag_mod"], tasks=rows,
                                  task_functions=funcs, cases="\n".join(cases))
    bodies = m.get("bodies")
    header = HEADER
    if bodies is not None:
        header = HEADER.replace(" --delay-ns {delay}\n", " --delay-ns {delay} \\\n *     --bodies {bodies}\n")
        header = header[:header.rindex(" */")] + WORK_HEADER.format(
            bodies=bodies["file"], work_n=bodies["work_words"], count_max=bodies["count_max"])
    head = header.format(
        name=m["name"], csv=m["inputs"]["csv"]["file"], map=m["inputs"]["map"]["file"],
        csv_sha=m["inputs"]["csv"]["sha256"], map_sha=m["inputs"]["map"]["sha256"],
        mesh=f"{w}x{h}", cpc=m["cycles_per_count"], reserve=m["reserve_cycles"],
        div=m["payload_divisor"], tag_mod=m["tag_mod"], delay=m["release"]["delay_ns"],
        n_tasks=len(tasks), n_flows=len(flows), n_remote=sum(not f["local"] for f in flows),
        period=m["release"]["period_ns"], release_pes=", ".join(str(n) for n in m["release"]["pes"]),
        **({"bodies": bodies["file"]} if bodies is not None else {}))
    if bodies is not None:
        return head + WORK_BODY.format(
            n_tasks=len(tasks), max_in=max_in, max_out=max_out, max_release=max_release, tag_mod=m["tag_mod"],
            work_n=bodies["work_words"], count_max=bodies["count_max"],
            max_repeat=max(t["repeat"] for t in tasks), tasks=rows, task_functions=funcs,
            cases="\n".join(cases))
    return head + BODY.format(n_tasks=len(tasks), max_in=max_in, max_out=max_out,
                              max_release=max_release, tag_mod=m["tag_mod"], tasks=rows,
                              task_functions=funcs, cases="\n".join(cases))


COMPOSITION_HEADER = """\
/*
 * {name}.c: UCX-OS image of a composition of applications generated by
 * rttools.ucxgen (orca-rt-tools). Do not edit: change the inputs and run
 * the generator again.
 *
 *   python -m rttools.ucxgen compose {app_args} \\
 *     --name {name} --mesh {mesh} --cycles-per-count {cpc} \\
 *     --payload-divisor {div} --tag-mod {tag_mod} --delay-ns {delay}
 *
{inputs}
 * {n_tasks} tasks, {n_flows} flows ({n_remote} between PEs), mesh {mesh}; release every
 * {period} ns after {delay} ns on the PEs of the source tasks ({release_pes}).
 *
 * Each PE runs the tasks of one application. Ports, flow numbers (tags)
 * and marker letters are numbered across the applications in the order
 * above, so a tag or a letter of the log identifies its application
 * (manifest {name}.json, field "apps"). The task pattern is the one of an
 * application of rttools.ucxgen generate (see the header of a generated
 * application, e.g. car_v.c): release of the source tasks by
 * irq4_handler, k-th packet of each input edge, ucx_sleep(workload), one
 * send per output edge, tag = flow * TAG_MOD + (k mod TAG_MOD), ITER
 * markers.
 */
"""


def composition_header(m):
    w, h = m["mesh"]
    apps = m["apps"]
    lines = []
    for a in apps:
        i = a["inputs"]
        lines.append(f" * {a['name']}: {i['csv']['file']} (sha256 {i['csv']['sha256']})")
        lines.append(f" * {' ' * len(a['name'])}  {i['map']['file']} (sha256 {i['map']['sha256']})")
        lines.append(f" * {' ' * len(a['name'])}  {len(a['tasks'])} tasks, flows {a['flows'][0]} to {a['flows'][-1]}, "
                     f"PEs {', '.join(map(str, a['pes']))}, reserve {a['reserve_cycles']} cycles")
    return COMPOSITION_HEADER.format(
        name=m["name"], mesh=f"{w}x{h}", cpc=m["cycles_per_count"], div=m["payload_divisor"],
        tag_mod=m["tag_mod"], delay=m["release"]["delay_ns"],
        app_args=" ".join(f"--app {a['name']}:{a['inputs']['csv']['file']}:{a['inputs']['map']['file']}"
                          for a in apps),
        inputs="\n".join(lines), n_tasks=len(m["tasks"]), n_flows=len(m["flows"]),
        n_remote=sum(not f["local"] for f in m["flows"]), period=m["release"]["period_ns"],
        release_pes=", ".join(str(n) for n in m["release"]["pes"]))


def sim_setup(m):
    w, h = m["mesh"]
    r = m["release"]
    if m.get("model") == "time_triggered":
        return ("# Setup of manycore_top for app/{0}.c (rttools.ucxgen, time-triggered); read by\n"
                "# experiments/exp23/simulate.sh. RELEASE_MASK: bit k = PE with node index k\n"
                "# (PEs {1}). The phase is {2} ns: run simulate.sh with RELEASE_NS={2}\n"
                "# (release generator and tick of the kernel), first release at {3} ns.\n"
                "MESH={4}x{5}\nRELEASE_MASK={6}\n").format(
            m["name"], ", ".join(str(n) for n in r["pes"]), r["period_ns"], r["delay_ns"], w, h, r["mask"])
    return ("# Setup of manycore_top for app/{0}.c (rttools.ucxgen); read by\n"
            "# experiments/exp23/simulate.sh. RELEASE_MASK: bit k = PE with node index k\n"
            "# (PEs {1}). Release period {2} ns, first release at {3} ns: the\n"
            "# defaults of the release generator (manycore_pe.sv).\n"
            "MESH={4}x{5}\nRELEASE_MASK={6}\n").format(
        m["name"], ", ".join(str(n) for n in r["pes"]), r["period_ns"], r["delay_ns"], w, h, r["mask"])


def manifest(m):
    return json.dumps(m, indent=1) + "\n"


# ------------------------------------------------------------ time-triggered

TT_HEADER = """\
/*
 * {name}.c: UCX-OS application generated by rttools.ucxgen (orca-rt-tools).
 * Do not edit: change the inputs and run the generator again.
 *
 *   python -m rttools.ucxgen generate {csv} {map} --name {name} \\
 *     --mesh {mesh} --cycles-per-count {cpc} --reserve {reserve} \\
 *     --payload-divisor {div} --tag-mod {tag_mod} --delay-ns {delay}
 *
 * Inputs: {csv} (sha256 {csv_sha})
 *         {map} (sha256 {map_sha})
 * {n_tasks} tasks, {n_flows} flows ({n_remote} between PEs), mesh {mesh};
 * phase (tick) of {period} ns, {hyper} phases per hyperperiod; release
 * interrupt every {period} ns after {delay} ns on every PE with a task.
 *
 * Time-triggered tasks: general phase model of the analysis flow
 * (rttools/bench_t/multirate.py). The release interrupt (irq4_handler)
 * counts the phases; the kernel calls ucx_app_tick at the next tick,
 * before the scheduler (kernel/sched.c, -DUCX_APP_TICK), and the hook
 * releases job j of task v at phase o_v + j k_v (k_v = period of v in
 * phases). A released task reads the latest packet of each input edge
 * without waiting (lib/noc.c, -DUCX_NOC_LATEST: one queued packet per
 * source, the arrival does not wake the task), waits
 * ucx_sleep(workload) cycles, workload = (c(v) - {reserve}) / {cpc}, and
 * sends on edge e when its job number j (from 1) has (j - 1) mod m_e = 0,
 * with the job number in the first word of the payload and tag = flow *
 * TAG_MOD + (j mod TAG_MOD). The kernel dispatches the released tasks by
 * round robin in the creation order of each PE (the order of the model).
 *
 * Markers (include/device/cacc.h): ITER_BEGIN(letter, j) when job j has
 * read its inputs; then, for each input edge in the order of the task
 * row, a read marker ITER_BEGIN(letter of the source, 0x800000 | i) with
 * the job number i of the source that the job read (0: no packet yet);
 * ITER_END(letter, j) after the last send. The markers of one job start
 * are written with interrupts disabled, so the read markers follow the
 * begin marker of their job on the PE.
 */
"""

TT_BODY = """\
#include <ucx.h>

#define N_TASKS     {n_tasks}
#define MAX_IN      {max_in}
#define MAX_OUT     {max_out}
#define MAX_LOCAL   {max_local}
#define TAG_MOD     {tag_mod}
#define TAG(flow, k) ((uint16_t)((flow) * TAG_MOD + ((k) % TAG_MOD)))
#define READ_MARK(letter, i) set_iter_mark(ITER_MARK(letter, 0x800000u | ((uint32_t)(i) & 0x7FFFFFu)))

struct out_s {{
  uint16_t cpu;    /* PE of the target task (node index) */
  uint16_t port;   /* port of the target task */
  uint16_t bytes;  /* payload */
  uint16_t flow;   /* index of the edge (tag) */
  uint16_t every;  /* m_e: job j sends when (j - 1) mod every = 0 */
}};

struct task_s {{
  char name[5];
  char letter;                    /* letter of the markers */
  uint16_t port;
  int32_t workload;               /* counts of ucx_sleep */
  uint16_t period;                /* k_v: phases between two releases */
  uint16_t offset;                /* o_v: phase of the first release */
  uint8_t n_in, n_out;
  uint16_t in_port[MAX_IN];       /* port of the source task of each input edge */
  char in_letter[MAX_IN];         /* marker letter of the source task of each input edge */
  struct out_s out[MAX_OUT];
}};

static const struct task_s TASKS[N_TASKS] = {{
{tasks}
}};

/* ------------------------------ release (tick hook) */
static const struct task_s *local_task[MAX_LOCAL];
static struct tcb_s *local_tcb[MAX_LOCAL];
static volatile uint32_t released[MAX_LOCAL];
static int n_local = 0;
static volatile uint32_t irq_pending = 0;   /* release interrupts not applied yet */
static uint32_t phase = 0;                  /* index of the next phase */

/* release interrupt (manycore_pe.sv, every phase on every PE with a task) */
void irq4_handler(void)
{{
  _di();
  irq_pending++;

  /* flag interruption down */
  volatile int *irq_flag_down = (volatile int *)(0x2000004C);
  *irq_flag_down = !(*irq_flag_down);
  _ei();
}}

/* tick hook (kernel/sched.c, dispatch): releases the jobs of each phase
 * whose interrupt came since the previous tick */
void ucx_app_tick(void)
{{
  while (irq_pending) {{
    irq_pending--;
    for (int i = 0; i < n_local; i++) {{
      const struct task_s *t = local_task[i];
      if (phase >= t->offset && (phase - t->offset) % t->period == 0) {{
        released[i]++;
        if (local_tcb[i]->state == TASK_BLOCKED)
          local_tcb[i]->state = TASK_READY;
      }}
    }}
    phase++;
  }}
}}

/* ------------------------------ tasks */
static noc_packet_t *create_pkt(uint32_t bytes)
{{
  noc_packet_t *pkt = ucx_noc_create_packet(bytes);

  for (uint32_t i = 0; i < bytes; i++)
    pkt->data[i] = i;

  return pkt;
}}

/* blocks until job done + 1 is released; the test and the block run with
 * interrupts disabled, so a release between them is not lost */
static void wait_release(int li, uint32_t done)
{{
  _di();
  while (released[li] == done) {{
    kcb_p->tcb_p->state = TASK_BLOCKED;
    ucx_task_yield();
    _di();
  }}
  _ei();
}}

/* latest packet of each input edge (one queued packet per source): keeps
 * the job number of the source (first word of the payload) */
static void read_inputs(const struct task_s *t, uint32_t *last)
{{
  _di();
  while (ucx_noc_probe() > 0) {{
    noc_packet_t *pkt = ucx_noc_receive();
    uint16_t port = pkt->source_port;
    uint32_t job = *(volatile uint32_t *)pkt->data;

    for (int i = 0; i < t->n_in; i++)
      if (t->in_port[i] == port)
        last[i] = job;
    if (pkt->source_node != ucx_noc_cpu_id())
      ucx_free(pkt);
  }}
  _ei();
}}

static void run_task(const struct task_s *t, int li)
{{
  noc_packet_t *pkt[MAX_OUT];
  uint32_t last[MAX_IN];
  uint32_t done = 0;

  _ei();
  ucx_noc_comm_create(t->port);
  for (int o = 0; o < t->n_out; o++)
    pkt[o] = create_pkt(t->out[o].bytes);
  for (int i = 0; i < MAX_IN; i++)
    last[i] = 0;

  for (;;) {{
    wait_release(li, done);
    read_inputs(t, last);
    _di();
    ITER_BEGIN(t->letter, done + 1);
    for (int i = 0; i < t->n_in; i++)
      READ_MARK(t->in_letter[i], last[i]);
    _ei();

    /* simulate processing */
    ucx_sleep(t->workload);
    done++;

    for (int o = 0; o < t->n_out; o++) {{
      if ((done - 1) % t->out[o].every)
        continue;
      if (t->out[o].cpu == ucx_noc_cpu_id()) {{
        /* the target reads the buffer of this task: job number and
         * enqueue with interrupts disabled */
        _di();
        *(volatile uint32_t *)pkt[o]->data = done;
        ucx_noc_send(t->out[o].cpu, t->out[o].port, pkt[o], TAG(t->out[o].flow, done));
        _ei();
      }} else {{
        *(volatile uint32_t *)pkt[o]->data = done;
        ucx_noc_send(t->out[o].cpu, t->out[o].port, pkt[o], TAG(t->out[o].flow, done));
      }}
    }}
    ITER_END(t->letter, done);
  }}
}}

{task_functions}

void idle_task_p(void)
{{
  /* a yield can enter the idle task with interrupts disabled (wait_release) */
  _ei();
  for (;;)
    ;
}}

static void add_task(void (*fn)(void), const struct task_s *t)
{{
  ucx_task_add(fn, (char *)t->name, DEFAULT_STACK_SIZE, 0, 0, 0);
  local_task[n_local] = t;
  local_tcb[n_local] = kcb_p->tcb_p;   /* tcb of the task just added */
  released[n_local] = 0;
  n_local++;
}}

int32_t app_main(void)
{{
  /* idle must be ID = 0 */
  ucx_task_add(idle_task_p, "IDLE", DEFAULT_STACK_SIZE, 0, 0, 0);

  switch (ucx_noc_cpu_id()) {{
{cases}
  default:
    break;
  }}

  return 1;
}}
"""


def tt_task_row(t, flows, tasks_by_name):
    ins = [tasks_by_name[flows[i - 1]["source"]] for i in t["inputs"]]
    outs = []
    for i in t["outputs"]:
        f = flows[i - 1]
        outs.append(f"{{{f['dst_pe']}, {tasks_by_name[f['target']]['port']}, {f['bytes']}, {f['id']}, "
                    f"{f['every']}}}")
    in_txt = "{" + ", ".join(str(x["port"]) for x in ins or [{"port": 0}]) + "}"
    let_txt = "{" + ", ".join(f"'{x['iter_letter']}'" for x in ins) + "}" if ins else "{0}"
    out_txt = "{" + ", ".join(outs or ["{0, 0, 0, 0, 0}"]) + "}"
    return (f"  /* {t['name']}: PE {t['pe']} ({t['pe_label']}), position {t['order']}, c(v) = {t['wcet']}, "
            f"every {t['period_ticks']} phases, marker {t['iter_letter']} */\n"
            f"  {{{c_string(t['name'][:4])}, '{t['iter_letter']}', {t['port']}, {t['workload']}, "
            f"{t['period_ticks']}, {t['offset_ticks']}, {len(ins)}, {len(t['outputs'])}, "
            f"{in_txt}, {let_txt}, {out_txt}}},")


def tt_source(m):
    flows = m["flows"]
    tasks = m["tasks"]
    by_name = {t["name"]: t for t in tasks}
    index = {t["name"]: i for i, t in enumerate(tasks)}
    max_in = max(1, max(len(t["inputs"]) for t in tasks))
    max_out = max(1, max(len(t["outputs"]) for t in tasks))
    per_pe = {}
    for t in tasks:
        per_pe.setdefault(t["pe"], []).append(t)
    max_local = max(len(ts) for ts in per_pe.values())
    rows = "\n".join(tt_task_row(t, flows, by_name) for t in tasks)
    funcs = "\n".join(f"static void task_{t['ident']}(void) {{ run_task(&TASKS[{index[t['name']]}], {t['order']}); }}"
                      for t in tasks)
    cases = []
    for node in sorted(per_pe):
        ts = sorted(per_pe[node], key=lambda t: t["order"])
        cases.append(f"  case {node}: /* ({ts[0]['pe_label']}): {', '.join(t['name'] for t in ts)} */")
        for t in ts:
            cases.append(f"    add_task(task_{t['ident']}, &TASKS[{index[t['name']]}]);")
        cases.append("    break;")
    w, h = m["mesh"]
    head = TT_HEADER.format(
        name=m["name"], csv=m["inputs"]["csv"]["file"], map=m["inputs"]["map"]["file"],
        csv_sha=m["inputs"]["csv"]["sha256"], map_sha=m["inputs"]["map"]["sha256"],
        mesh=f"{w}x{h}", cpc=m["cycles_per_count"], reserve=m["reserve_cycles"],
        div=m["payload_divisor"], tag_mod=m["tag_mod"], delay=m["release"]["delay_ns"],
        n_tasks=len(tasks), n_flows=len(flows), n_remote=sum(not f["local"] for f in flows),
        period=m["release"]["period_ns"], hyper=m["hyper_ticks"])
    return head + TT_BODY.format(n_tasks=len(tasks), max_in=max_in, max_out=max_out, max_local=max_local,
                                 tag_mod=m["tag_mod"], tasks=rows, task_functions=funcs, cases="\n".join(cases))
